## This is the command used to create the SQANTI3 output for the example data

python3 sqanti3_qc.py --refGTF data/reference/gencode.v38.basic_chr22.gtf --refFasta data/reference/GRCh38.p13_chr22.fasta --cpus 4 --dir example/QC_isoforms --output UHR_chr22 --log_level INFO --isoforms data/UHR_chr22.gtf --sites ATAC,GCAG,GTAG --window 20 --aligner_choice minimap2 --include_ORF --psauron_threshold 0.5 --short_reads data/UHR_chr22_short_reads.fofn --CAGE_peak data/ref_TSS_annotation/human.refTSS_v3.1.hg38.bed --polyA_motif_list data/polyA_motifs/mouse_and_human.polyA_motif.txt --fl_count data/UHR_abundance.tsv --report both --ratio_TSS_metric max --chunks 1